    #[verus_spec(returns self.view())]
    fn deref(&self) -> &T {
        proof!{
            use_type_invariant(self);
        }
        self.inner.val.borrow(Tracked(self.tracked_token.borrow().borrow().0.borrow()))
    }
}


#[verus_verify]
impl<T               , G: SpinGuardian> RwLockReadGuard<'_, T, G> {
    #[verus_spec]
    fn drop(self) {
        proof! {
            use_type_invariant(&self);
            use_type_invariant(self.inner);
            lemma_consts_properties();
        }
        proof_decl! {
            let tracked token = self.tracked_token.get();
        }
        atomic_with_ghost!(
            self.inner.lock => fetch_sub(READER);
            update prev -> next;
            ghost g => {
                let prev_usize = prev as usize;
                assert(g.read_guard_token is Left);
                assert(g.read_guard_token.left().frac() < MAX_READER_U64);
                assert(MAX_READER_U64 - g.read_guard_token.left().frac() >= 1);
                assert(no_max_reader_overflow(prev_usize));
                match &mut g.read_guard_token {
                    Sum::Left(read_guard_token) => {
                        read_guard_token.combine(token);
                    },
                    Sum::Right(_) => { proof_from_false() },
                }
            }
        );
    }

    }
}

